input.old_string:
input { width: 100%; padding: 10px 12px; margin-bottom: 4px; border: 1px solid #c8c2b8; border-radius: 6px; font-size: 15px }
.field { margin-bottom: 16px }
.error { font-size: 13px; color: #e2685f; min-height: 16px }
.summary { color: #e2685f; font-size: 14px; margin-bottom: 18px }
button { width: 100%; padding: 12px; background: #6b4d2e; color: #fff; border: 0; border-radius: 6px; font-size: 15px; font-weight: 600; cursor: pointer; margin-top: 6px }
.secure { font-size: 12px; color: #6f675c; margin-top: 14px; text-align: center }

input.new_string:
input { width: 100%; padding: 10px 12px; margin-bottom: 4px; border: 1px solid #8a8272; border-radius: 6px; font-size: 15px }
.field { margin-bottom: 16px }
.error { font-size: 13px; color: #c1443b; min-height: 16px }
.summary { color: #c1443b; font-size: 14px; margin-bottom: 18px }
button { width: 100%; padding: 12px; background: #6b4d2e; color: #fff; border: 0; border-radius: 6px; font-size: 15px; font-weight: 600; cursor: pointer; margin-top: 6px }
.secure { font-size: 12px; color: #6f675c; margin-top: 14px; text-align: center }
input:focus-visible, button:focus-visible { outline: 3px solid #2d2620; outline-offset: 2px }

